    static int[] dsuParent;
    static int[] dsuSize;
    static int[] treeRoot;
    static int[] treeParent;
    static long[] mass;
    static long[] threshold;
    static int nodeCount;

    static int find(int x) {
        int root = x;
        while (dsuParent[root] != root) {
            root = dsuParent[root];
        }
        while (dsuParent[x] != x) {
            int next = dsuParent[x];
            dsuParent[x] = root;
            x = next;
        }
        return root;
    }

    static void unite(int a, int b, long weight) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return;

        int node = nodeCount++;
        int left = treeRoot[ra];
        int right = treeRoot[rb];

        mass[node] = mass[left] + mass[right];
        threshold[node] = weight;
        treeParent[left] = node;
        treeParent[right] = node;

        if (dsuSize[ra] < dsuSize[rb]) {
            int temp = ra;
            ra = rb;
            rb = temp;
        }
        dsuParent[rb] = ra;
        dsuSize[ra] += dsuSize[rb];
        treeRoot[ra] = node;
    }

    public static void main(String[] args) throws Exception {
