        int n = fs.nextInt();
        int m = fs.nextInt();
        int v = n * m;

        long[] values = new long[v];
        long[] order = new long[v];
        final int SHIFT = 17;
        final long MASK = (1L << SHIFT) - 1;

        for (int i = 0; i < v; i++) {
            values[i] = fs.nextLong();
            order[i] = (values[i] << SHIFT) | i;
        }
