        threshold = new long[maxNodes];
        int[] startNode = new int[v];

        nodeCount = v;
        Arrays.fill(dsuParent, -1);
        for (int i = 0; i < v; i++) {
            mass[i] = values[i];
            threshold[i] = values[i];
        }

        int pos = 0;
        while (pos < v) {
            long weight = order[pos] >>> SHIFT;
            int end = pos + 1;
            while (end < v && (order[end] >>> SHIFT) == weight) end++;

            for (int k = pos; k < end; k++) {
                int cell = (int) (order[k] & MASK);
                dsuParent[cell] = cell;
                dsuSize[cell] = 1;
                treeRoot[cell] = cell;
            }

            for (int k = pos; k < end; k++) {
                int cell = (int) (order[k] & MASK);
                int row = cell / m;
                int col = cell % m;

