                    unite(cell, cell + m, weight);
                if (col > 0 && dsuParent[cell - 1] != -1)
                    unite(cell, cell - 1, weight);
                if (col + 1 < m && dsuParent[cell + 1] != -1)
                    unite(cell, cell + 1, weight);
            }

            for (int k = pos; k < end; k++) {
                int cell = (int) (order[k] & MASK);
                startNode[cell] = treeRoot[find(cell)];
            }

            pos = end;
        }

        int[] terminal = new int[nodeCount];
        for (int i = nodeCount - 1; i >= 0; i--) {
            int p = treeParent[i];
            if (p != -1 && threshold[p] <= mass[i]) {
                terminal[i] = terminal[p];
            } else {
                terminal[i] = i;
            }
        }

        StringBuilder out = new StringBuilder();
        for (int row = 0; row < n; row++) {
            for (int col = 0; col < m; col++) {
                if (col > 0) out.append(' ');
                int cell = row * m + col;
                out.append(mass[terminal[startNode[cell]]]);
            }
            out.append('\n');
        }
        System.out.print(out);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}
